-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.access_status(terms_version text DEFAULT NULL::text, privacy_version text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when not coalesce(public.is_allowed_user(), false) then 'not_invited'
    when not public.token_session_open() then 'signed_out'
    when access_status.terms_version is null and access_status.privacy_version is null then 'allowed'
    when exists (
      select 1 from public.legal_acceptances a
       where a.user_id = auth.uid()
         and a.terms_version = access_status.terms_version
         and a.privacy_version = access_status.privacy_version) then 'allowed'
    else 'not_accepted'
  end;
$function$;

grant execute on function public.access_status(terms_version text, privacy_version text) to authenticated;
grant execute on function public.access_status(terms_version text, privacy_version text) to service_role;
